sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float2 offset;
uniform float count;
uniform float2 stretch;
uniform float width;
layout(color) uniform half4 color;
uniform float punch;
uniform float angle;
uniform float origin;
uniform float smoothing;
uniform float spacing;
uniform float style;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float tall = origin > 1.5 ? screen.w : size.y;
    if (style > 0.5 && spacing <= 0.0) return src;
    float cell = style > 0.5 ? spacing * tall : tall / (2.475 * max(count, 0.5));
    float a = radians(angle);
    float2 dims = max(abs(stretch), float2(0.01)) * cell;
    float2 start = origin > 1.5 ? screen.xy + 0.5 * dims : origin > 0.5 ? 0.5 * dims : size * 0.5;
    if (style > 0.5 && origin > 0.5) start += 0.5 * tall;
    float2 p = coord - start - offset;
    p = float2(cos(a) * p.x + sin(a) * p.y, -sin(a) * p.x + cos(a) * p.y) / dims;
    float2 e = abs(fract(p + 0.5) - 0.5) * dims;
    float half_ = width * 0.5 * (style > 0.5 ? tall : cell);
    float soft = max(smoothing, 0.0) * 0.05 * tall;
    float s = width <= 0.0 ? 0.0 : style > 0.5 && soft > 0.0 ? 1.0 - smoothstep(half_ - soft, half_ + soft, min(e.x, e.y)) : clamp(half_ - min(e.x, e.y) + 0.5, 0.0, 1.0);
    if (punch > 0.5) return src * half(1.0 - s);
    float3 base = float3(src.rgb) / float(src.a);
    float w = s * float(color.a);
    float3 rgb = style > 0.5 ? base * (1.0 - w) + float3(color.rgb) * w * w : mix(base, float3(color.rgb), w);
    return half4(half3(rgb) * src.a, src.a);
}
